mapper.select:
SELECT DISTINCT u.id, u.create_time, u.create_by, u.update_time, u.update_by, u.data_status, u.del_flag, u.tenant_id, u.org_id, u.account, u.mobile, u.password, u.user_name, u.birthday, u.gender, u.avatar, u.nick_name, u.locked, u.enabled FROM sys_user u
LEFT JOIN sys_user_org_rel rel ON u.id = rel.user_id AND rel.del_flag = 0
u.del_flag = 0
AND u.enabled = #{enabled}
AND u.locked = #{locked}
AND ( u.org_id IN
#{orgId}
OR rel.org_id IN
#{orgId}
)
AND ( u.account LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.mobile LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY u.create_time DESC, u.id DESC
